const input = $input.first().json;

// Si ya viene una URL directa específica, no requiere motor de búsqueda
if (input.targetUrl && typeof input.targetUrl === 'string' && input.targetUrl.startsWith('http')) {
  return [{
    json: {
      direct_url: input.targetUrl.trim(),
      search_query: null,
      source_name: input.sourceName || 'Búsqueda Directa',
      vertical: input.vertical || 'real_estate',
      location: input.location || 'Panamá',
      is_direct: true
    }
  }];
}

// Construir la consulta de búsqueda flexible y no restrictiva para Panamá
const loc = (input.location && input.location !== 'Panamá') ? input.location.trim() : '';
const vert = input.vertical || 'real_estate';
const budget = Number(input.budget) || 0;
const queryText = input.searchQuery || '';

let composedQuery = '';
if (queryText) {
  composedQuery = `${queryText}`;
} else if (vert === 'vehicles') {
  composedQuery = `autos vehiculos venta ${loc} Panamá ${budget > 0 ? `hasta ${budget}` : ''} site:encuentra24.com OR site:banconal.com.pa OR site:cajadeahorros.com.pa`;
} else {
  composedQuery = `propiedades apartamentos casas venta ${loc} Panamá ${budget > 0 ? `hasta ${budget}` : ''} site:encuentra24.com OR site:compreoalquile.com OR site:banconal.com.pa`;
}

return [{
  json: {
    direct_url: null,
    search_query: composedQuery.replace(/\s+/g, ' ').trim(),
    source_name: `Búsqueda Web (${loc || 'Panamá'})`,
    vertical: vert,
    location: loc || 'Panamá',
    is_direct: false
  }
}];

// Extractor de URLs relevantes adaptado del patrón Scrapeador_master
const htmlData = $input.first().json.data || '';
const searchMeta = $('Construir Consulta de Búsqueda').first().json;

// 1. Extraer todos los enlaces de resultados de búsqueda
const regex = /href="([^"]+)"/g;
let match;
const rawLinks = [];

while ((match = regex.exec(htmlData)) !== null) {
  let link = match[1];
  if (link.includes('uddg=')) {
    try {
      const parts = link.split('uddg=');
      if (parts[1]) {
        link = decodeURIComponent(parts[1].split('&')[0]);
      }
    } catch (e) {}
  }

  if (link.startsWith('http')) {
    rawLinks.push(link);
  }
}

// 2. Filtrar solo portales y bancos de Panamá válidos (excluyendo rastreadores y ads)
const allowedDomains = ['encuentra24.com', 'compreoalquile.com', 'banconal.com.pa', 'cajadeahorros.com.pa', 'baccredomatic.com', 'kwpanama.com', 'bgeneral.com'];
const excludedPatterns = ['facebook.com', 'twitter.com', 'instagram.com', 'duckduckgo.com', 'google.com', 'youtube.com', '/login', '/signup', '/registro'];

const validUrls = [];
for (const url of rawLinks) {
  const isAllowed = allowedDomains.some(dom => url.toLowerCase().includes(dom));
  const isExcluded = excludedPatterns.some(ex => url.toLowerCase().includes(ex));

  if (isAllowed && !isExcluded) {
    const isPdf = url.toLowerCase().endsWith('.pdf') || url.toLowerCase().includes('/pdf/');
    validUrls.push({
      url: url,
      source_name: searchMeta.source_name || 'Búsqueda Web',
      vertical: searchMeta.vertical || 'real_estate',
      location: searchMeta.location || 'Panamá',
      is_pdf: isPdf,
      is_custom_trigger: true
    });
  }
}

// Si no hay resultados de búsqueda, devolver indicador para Token Guard
if (validUrls.length === 0) {
  return [{
    json: {
      no_search_results: true,
      location: searchMeta.location || 'Panamá',
      query: searchMeta.search_query
    }
  }];
}

const topUrls = validUrls.slice(0, 4);
return topUrls.map(item => ({ json: item }));

const item = $input.first().json;
const isPdf = (item.direct_url || '').toLowerCase().endsWith('.pdf') || (item.direct_url || '').toLowerCase().includes('/pdf/');
return [{
  json: {
    url: item.direct_url,
    source_name: item.source_name,
    vertical: item.vertical,
    location: item.location || 'Panamá',
    is_pdf: isPdf,
    is_custom_trigger: true
  }
}];

const items = $input.all();
const validSources = [];

for (const item of items) {
  const s = item.json;
  if (s && s.source_id && s.base_url) {
    const targetUrl = s.base_url;
    const isPdf = targetUrl.toLowerCase().endsWith('.pdf') || targetUrl.toLowerCase().includes('/pdf/');
    validSources.push({
      source_id: s.source_id,
      url: targetUrl,
      source_name: s.display_name || s.name,
      vertical: s.vertical || 'real_estate',
      is_pdf: isPdf,
      is_custom_trigger: false
    });
  }
}

if (validSources.length === 0) {
  throw new Error('No se encontraron fuentes activas en Supabase o falló la conexión.');
}

return validSources.map(src => ({ json: src }));

