// Normalizar schema HOIE y calcular UUID determinista para Supabase
const parsed = $json.output || $json;
const list = Array.isArray(parsed.assets) ? parsed.assets : [];
const validItems = [];

const baseUrl = $json.url || '';
const rawSource = $json.source_name || 'Desconocido';

function generateDeterministicUUID(seed) {
  let hash1 = 0x811c9dc5;
  let hash2 = 0x5bd1e995;
  for (let i = 0; i < seed.length; i++) {
    const ch = seed.charCodeAt(i);
    hash1 = Math.imul(hash1 ^ ch, 0x01000193);
    hash2 = Math.imul(hash2 ^ (ch << 1), 0x5bd1e995);
  }
  const hex1 = ('00000000' + (hash1 >>> 0).toString(16)).slice(-8);
  const hex2 = ('00000000' + (hash2 >>> 0).toString(16)).slice(-8);
  const hex3 = ('00000000' + ((hash1 ^ hash2) >>> 0).toString(16)).slice(-8);
  const hex4 = ('00000000' + ((hash1 + hash2) >>> 0).toString(16)).slice(-8);
  const fullHex = (hex1 + hex2 + hex3 + hex4).slice(0, 32);

  return (
    fullHex.substring(0, 8) + '-' +
    fullHex.substring(8, 12) + '-' +
    '4' + fullHex.substring(13, 16) + '-' +
    ((parseInt(fullHex.substring(16, 18), 16) & 0x3f) | 0x80).toString(16) + fullHex.substring(18, 20) + '-' +
    fullHex.substring(20, 32)
  );
}

let sourceId = $json.source_id;
const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!sourceId || !isUuid.test(sourceId)) {
  sourceId = generateDeterministicUUID('source::' + rawSource.toLowerCase());
}

for (const item of list) {
  const price = Number(item.price_amount);
  if (!item.title || isNaN(price) || price <= 0) continue;

  const listingUrl = (item.source_listing_url && item.source_listing_url.startsWith('http')) 
    ? item.source_listing_url.trim() 
    : baseUrl;

  const normalizedTitle = String(item.title)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .replace(/\s+/g, ' ');

  const isUniqueUrl = (listingUrl !== baseUrl && listingUrl.length > 0);
  const hashSeed = isUniqueUrl 
    ? sourceId + '::' + listingUrl
    : sourceId + '::' + listingUrl + '::' + normalizedTitle;

  const assetId = generateDeterministicUUID(hashSeed);

  const loc = item.location || {};
  const province = loc.province || 'Panamá';
  const corregimiento = loc.corregimiento || 'Bella Vista';
  const district = loc.district || (province === 'Panamá' ? 'Panamá' : corregimiento);

  validItems.push({
    asset_id: assetId,
    source_id: sourceId,
    source_listing_url: listingUrl,
    vertical: item.vertical === 'vehicles' ? 'vehicles' : 'real_estate',
    title: String(item.title).trim(),
    description: item.description || '',
    price_amount: price,
    price_currency: 'USD',
    location: { ...loc, province, district, corregimiento },
    raw_data: {
      specs: item.specs || {},
      area_m2: item.specs?.area_m2 || null,
      bedrooms: item.specs?.bedrooms || null,
      bathrooms: item.specs?.bathrooms || null,
      extracted_by: 'n8n_discovery_groq_pipeline',
      extracted_at: new Date().toISOString()
    },
    status: 'active',
    updated_at: new Date().toISOString()
  });
}

if (validItems.length === 0) {
  return [{
    json: {
      is_empty_error: true,
      source_name: rawSource,
      url: baseUrl
    }
  }];
}

return validItems.map(obj => ({ json: obj }));

