const items = $input.all();
const prices = items.map(item => Number(item.json.price_amount)).filter(p => !isNaN(p) && p > 0);

const currentAsset = $('Normalizar & Hash Inmutable').item.json;
const currentPrice = Number(currentAsset.price_amount);
const vertical = currentAsset.vertical;

let isOpportunity = false;
let reason = '';
let avgPrice = 0;

if (vertical === 'vehicles') {
  isOpportunity = currentPrice <= 25000;
  reason = `Auto bajo límite estático de $25,000 (Precio actual: $${currentPrice.toLocaleString('en-US')})`;
} else {
  if (prices.length >= 3) {
    const sum = prices.reduce((a, b) => a + b, 0);
    avgPrice = Math.round(sum / prices.length);
    const discount = ((avgPrice - currentPrice) / avgPrice) * 100;
    isOpportunity = discount >= 15;
    reason = `Precio actual ($${currentPrice.toLocaleString('en-US')}) es ${discount.toFixed(1)}% menor al promedio de la zona ($${avgPrice.toLocaleString('en-US')}) basado en ${prices.length} activos`;
  } else {
    isOpportunity = currentPrice <= 180000;
    reason = `Datos insuficientes en zona. Oportunidad bajo límite estático de $180,000 (Precio actual: $${currentPrice.toLocaleString('en-US')})`;
  }
}

return [{ 
  json: {
    ...currentAsset,
    is_opportunity: isOpportunity,
    opportunity_reason: reason,
    avg_zone_price: avgPrice || null
  }
}];

